"use strict";
/* aichallenge.js - AI Challenge: Python questions generated by the backend AI.  The SERVER writes, hides the answers of, and grades every question;
   this file only shows the question, sends the player's answer, and displays the verdict.  It never changes ammo, health, score or credits. */
const AIQ={q:null,busy:false,seq:0,timeoutMs:30000,
 base(){return(GHOST_CONFIG.apiBase||'').replace(/\/+$/,'')},
 async api(path,body){const ac=new AbortController(),t=setTimeout(()=>ac.abort(),this.timeoutMs);
  try{const r=await fetch(this.base()+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:ac.signal});let d=null;try{d=await r.json()}catch(e){}
   if(!r.ok){const e=new Error((d&&d.message)||'HTTP '+r.status);e.code=d&&d.error;throw e}return d}
  catch(e){if(e.name==='AbortError'){const x=new Error('The AI took too long to answer.');x.code='timeout';throw x}throw e}finally{clearTimeout(t)}},
 fb(t,cls){const f=$('aiqFb');f.textContent=t;f.className='t'+(cls?' '+cls:'')},
 stats(){const s=SAVE.aiq;$('aiqStat').textContent='Answered '+s.n+'  |  Correct '+s.ok},
 lock(on){['aiqIn','aiqSend','aiqHintB','aiqGive'].forEach(i=>$(i).disabled=on)},
 open(){if(state!=='menu')return;state='aiq';show('aiq');this.stats();if(!this.q||this.q.done)this.next();else setTimeout(()=>this.focus(),50)},
 close(){if(state!=='aiq')return;this.seq++;this.busy=false;state='menu';show('menu')},
 focus(){if(!(window.matchMedia&&matchMedia('(pointer:coarse)').matches)&&!$('aiqIn').disabled)$('aiqIn').focus()},
 async next(){if(this.busy)return;const seq=++this.seq;this.busy=true;this.q=null;$('aiqMeta').textContent='';$('aiqHint').style.display='none';$('aiqIn').value='';this.fb('');this.lock(true);$('aiqNext').disabled=true;
  if(!this.base()){$('aiqQ').textContent='AI Challenge needs the online AI service, and this copy of the game is not connected to one. Practice Mode works fully offline.';$('aiqNext').disabled=false;this.busy=false;return}
  $('aiqQ').textContent='Generating a question...';
  try{const d=await this.api('/api/questions/generate',{level:clamp(+SAVE.lvl||1,1,10),recent:SAVE.aiq.recent});if(seq!==this.seq)return;this.q=d.question;this.render(d)}
  catch(e){if(seq===this.seq)$('aiqQ').textContent='The AI is temporarily unavailable ('+e.message+'). Try again in a moment, or use Practice Mode.'}
  finally{if(seq===this.seq){this.busy=false;$('aiqNext').disabled=false}}},
 render(d){const q=this.q;$('aiqMeta').textContent='Topic: '+q.topic+'  |  Difficulty '+q.difficulty+'/5  |  '+(q.source==='ai'?'AI-generated':'Offline question bank (AI unavailable)');$('aiqQ').textContent=q.question;this.fb(d.note||'');this.lock(false);setTimeout(()=>this.focus(),50)},
 record(q,ok){const s=SAVE.aiq;s.recent.push({difficulty:q.difficulty,correct:ok,topic:q.topic,q:q.question});s.recent=s.recent.slice(-10);s.n++;if(ok)s.ok++;store();this.stats()},
 result(r,q){if(r.correct){q.done=true;this.record(q,true);this.lock(true);$('aiqIn').disabled=true;this.fb('Correct! '+(r.explanation||''),'good');$('aiqNext').focus()}
  else if(r.finished){q.done=true;this.record(q,false);this.lock(true);this.fb((r.feedback||'')+'  Explanation: '+(r.explanation||''),'bad');$('aiqNext').focus()}
  else this.fb((r.feedback||'Not quite.')+'  (try '+r.attempts+' of 4)','bad')},
 async check(){if(this.busy||!this.q||this.q.done)return;const a=$('aiqIn').value.trim();if(!a){this.fb('Type your answer first.');return}
  this.busy=true;this.lock(true);this.fb('Checking...');const seq=this.seq,q=this.q;
  try{const r=await this.api('/api/questions/evaluate',{id:q.id,answer:a});if(seq===this.seq)this.result(r,q)}
  catch(e){if(seq===this.seq)this.fb(e.code==='unknown_question'?'That question expired. Press NEXT QUESTION.':'The AI grader is temporarily unavailable ('+e.message+'). Your answer was not marked wrong. Try again.','bad')}
  finally{if(seq===this.seq){this.busy=false;if(!q.done)this.lock(false)}}},
 async give(){if(this.busy||!this.q||this.q.done)return;this.busy=true;this.lock(true);const seq=this.seq,q=this.q;
  try{const r=await this.api('/api/questions/evaluate',{id:q.id,give_up:true});if(seq===this.seq){q.done=true;this.record(q,false);this.fb('Explanation: '+(r.explanation||''),'bad');$('aiqNext').focus()}}
  catch(e){if(seq===this.seq)this.fb('Could not load the explanation ('+e.message+').','bad')}
  finally{if(seq===this.seq){this.busy=false;if(!q.done)this.lock(false)}}},
 hint(){if(this.q&&this.q.hint){const h=$('aiqHint');h.textContent='Hint: '+this.q.hint;h.style.display=''}}};
$('aiqb').onclick=()=>AIQ.open();$('aiqClose').onclick=()=>AIQ.close();$('aiqNext').onclick=()=>AIQ.next();$('aiqSend').onclick=()=>AIQ.check();$('aiqHintB').onclick=()=>AIQ.hint();$('aiqGive').onclick=()=>AIQ.give();
$('aiqIn').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();AIQ.check()}});
